from google.cloud import monitoring_v3
from google.protobuf.timestamp_pb2 import Timestamp

def filter_metric_dimensions(payload, config=None):
    config = config or {}
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT", config.get("gcp_project_id"))
    if not project_id:
        raise ValueError("Google Cloud project ID not set in GOOGLE_CLOUD_PROJECT environment variable or config")

    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    filter_conditions = [f'metric.type = "{payload["metric_type"]}"']
    if "filters" in payload:
        for key, value in payload["filters"].items():
            filter_conditions.append(f'{key} = "{value}"')

    metric_filter = " AND ".join(filter_conditions)

    now = time.time()
    seconds = int(now)
    nanos = int((now - seconds) * 10**9)

    # Query the last 20 minutes of data
    interval = monitoring_v3.TimeInterval(
        {
            "end_time": Timestamp(seconds=seconds, nanos=nanos),
            "start_time": Timestamp(seconds=(seconds - 1200), nanos=nanos),
        }
    )

    request = {
        "name": project_name,
        "filter": metric_filter,
        "interval": interval,
        "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
    }

    # API call
    time_series = client.list_time_series(request)

    # Process response
    output = []
    for series in time_series:
        series_info = {
            "metric_labels": dict(series.metric.labels),
            "resource_labels": dict(series.resource.labels),
            "points": []
        }
        for point in series.points:
            point_data = {
                "timestamp": point.interval.end_time.rfc3339(),
                "value": point.value.double_value if series.value_type.name == 'DOUBLE' else point.value.int64_value
            }
            series_info["points"].append(point_data)
        output.append(series_info)

    result = output
    return result
